<div class="page-head"><div><h1>E-mailové schránky</h1><div class="sub">Správa adres na vlastním mailserveru Byznio. Zákaznické schránky nesmí používat vyhrazené systémové názvy.</div></div></div><div class="card"><h3>Nová schránka</h3><form class="form" method="post" action="/admin/mailboxes"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Adresa</label><div style="display:flex;gap:8px;align-items:center"><input name="localpart" placeholder="novak" required><span>@<?=\App\Core\View::e($domain)?></span></div></div><div class="field"><label>Zobrazené jméno odesílatele</label><input name="display_name" placeholder="Jan Novák"></div></div><div class="row"><div class="field"><label>Firma zákazníka</label><select name="workspace_id"><option value="">— systémová schránka —</option><?php foreach($workspaces as $w):?><option value="<?=$w['id']?>"><?=\App\Core\View::e($w['name'])?> (<?=\App\Core\View::e($w['email_localpart'])?>@<?=\App\Core\View::e($domain)?>)</option><?php endforeach;?></select></div><div class="field"><label>Heslo schránky (volitelné)</label><input type="password" name="password" minlength="10" autocomplete="new-password"></div></div><label><input type="checkbox" name="is_system" value="1"> Systémová / Byznio schránka</label><p class="sub">Vyhrazené názvy: <?=\App\Core\View::e(implode(', ',$reserved))?>. Ty může použít pouze Super Admin jako systémovou schránku.</p><button class="btn primary">Vytvořit schránku</button></form></div><div class="card" style="margin-top:16px"><h3>Existující schránky</h3><div class="tablewrap"><table class="table"><tr><th>Adresa</th><th>Jméno</th><th>Firma</th><th>Typ</th><th>Stav</th><th></th></tr><?php foreach($rows as $r):?><tr><td><a href="/admin/mailboxes/<?=$r['id']?>"><b><?=\App\Core\View::e($r['localpart'])?>@<?=\App\Core\View::e($domain)?></b></a></td><td><?=\App\Core\View::e($r['display_name'])?></td><td><?=\App\Core\View::e($r['workspace_name']??'—')?></td><td><?=((int)$r['is_system'])?'Byznio':'zákazník'?></td><td><?=((int)$r['active'])?'Aktivní':'Vypnutá'?></td><td><form method="post" action="/admin/mailboxes/<?=$r['id']?>/toggle"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><button class="btn"><?=((int)$r['active'])?'Vypnout':'Zapnout'?></button></form></td></tr><?php endforeach;?></table></div></div>